package org.millenaire.common.entity;import net.minecraft.world.entity.*;import org.millenaire.common.utilities.*;import org.millenaire.common.village.*;import org.millenaire.common.item.*;public class MillVillager extends Entity{public boolean extraLog;public java.util.Map<net.minecraft.world.item.Item,Integer> inventory;public Building getTownHall(){return house;}public void addToInv(net.minecraft.world.item.Item i,int n){inventory.merge(i,n,Integer::sum);}public void addToInv(net.minecraft.world.level.block.Block b,int n){addToInv(b.asItem(),n);}public Building house;public LivingEntity target;public int swings;public Entity destination;public MillVillager(){super(EntityType.PIG,null);}protected void defineSynchedData(){}protected void readAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}protected void addAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}public net.minecraft.network.protocol.Packet<?> getAddEntityPacket(){return null;}public Building getHouse(){return house;}public Building getGoalBuildingDest(){return house;}public Entity getGoalDestEntity(){return destination;}public Point getPos(){return new Point();}public boolean canVillagerClearLeaves(){return false;}public boolean hasLineOfSight(Entity e){return true;}public void setTarget(LivingEntity e){target=e;}public void addToInv(InvItem i,int n){}public void swing(net.minecraft.world.InteractionHand h){swings++;}}